function seededAtmosphere(seed:number,count:number,radius:number):AmbientParticle[]{
  let value=seed;const particles:AmbientParticle[]=[];
  for(let i=0;i<count;i+=1){value=(value*48271)%2147483647;const angle=value/2147483647*Math.PI*2;value=(value*48271)%2147483647;const distance=Math.sqrt(value/2147483647)*radius;value=(value*48271)%2147483647;particles.push({x:Math.cos(angle)*distance,y:Math.sin(angle)*distance,phase:value/2147483647*Math.PI*2,size:1.5+(i%5)*.72,drift:.55+(i%7)*.11});}
  return particles;
}
