function rarityForName(name: string, fallback: Rarity = "Common"): Rarity { return trinketByName(name)?.rarity ?? (Object.values(RARE_LOOT).some(item => item.name === name) ? "Relic" : fallback); }
function applyRareLoot(save: PersistedSave, rareId: RareLootId): PersistedSave {
  const item = RARE_LOOT[rareId];
  const items = [...new Set([...save.items, item.name])].slice(-60);
  if (rareId === "emberbrand") return { ...save, weaponName: item.name, weaponDamage: Math.max(save.weaponDamage, 32), rarity: "Relic", items };
  if (rareId === "winterstring") return { ...save, weaponName: item.name, weaponDamage: Math.max(save.weaponDamage, 29), attackSpeed: Math.max(save.attackSpeed, 1.2), rarity: "Relic", items };
  if (rareId === "nightkiss") return { ...save, weaponName: item.name, weaponDamage: Math.max(save.weaponDamage, 25), attackSpeed: Math.max(save.attackSpeed, 1.45), lifesteal: Math.max(save.lifesteal, .18), rarity: "Relic", items };
  if (rareId === "mirrorplate") return { ...save, armorName: item.name, armorDefense: Math.max(save.armorDefense, 20), thorns: Math.max(save.thorns, .3), items };
  if (rareId === "ashheart") return { ...save, weaponName: item.name, weaponDamage: Math.max(save.weaponDamage, 48), critChance: Math.max(save.critChance, .16), rarity: "Relic", items };
  if (rareId === "mirecrown") return { ...save, armorName: item.name, armorDefense: Math.max(save.armorDefense, 28), thorns: Math.max(save.thorns, .42), maxHp: Math.max(save.maxHp, 170), items };
  if (rareId === "starshard") return { ...save, weaponName: item.name, weaponDamage: Math.max(save.weaponDamage, 38), attackSpeed: Math.max(save.attackSpeed, 1.7), critChance: Math.max(save.critChance, .24), rarity: "Relic", items };
  if (rareId === "tyrantcinder") return { ...save, weaponName: item.name, weaponDamage: Math.max(save.weaponDamage, 56), maxHp: Math.max(save.maxHp, 190), hp: Math.max(save.hp, 190), rarity: "Relic", items };
  if (rareId === "ashwatch") return { ...save, weaponName: item.name, weaponDamage: Math.max(save.weaponDamage, 44), attackSpeed: Math.max(save.attackSpeed, 1.55), critChance: Math.max(save.critChance, .2), rarity: "Relic", items };
  if (rareId === "mirestride") return { ...save, armorName: item.name, armorDefense: Math.max(save.armorDefense, 14), moveSpeed: Math.max(save.moveSpeed, .18), items };
  return { ...save, armorName: item.name, armorDefense: Math.max(save.armorDefense, 10), moveSpeed: Math.max(save.moveSpeed, .12), items };
}
