function expandedSpawns(regionId:number,radius:number,base:RegionSpawn[],kinds:EnemyKind[],count:number):RegionSpawn[]{
  let seed=regionId*7919+104729;const random=()=>{seed=(seed*48271)%2147483647;return seed/2147483647;};const spawns=[...base];
  for(let i=base.length;i<count;i+=1){const angle=random()*Math.PI*2,distance=radius*(.2+Math.sqrt(random())*.68),kind=kinds[Math.floor(random()*kinds.length)]??"bat";spawns.push({x:Math.cos(angle)*distance,y:Math.sin(angle)*distance,kind,elite:i>base.length&&i%13===0});}
  return spawns;
}
