const NPC_DIALOGUE: Record<NpcId,{history:[string,string];world:string;detail:string;voices:Record<VoiceKind,string[]>}> = {
  mara:{history:["I was a field nurse before the dead rose. When Hearthglen lost its doctor, everyone started knocking on my door.","My husband Tomas held the south gate during the first outbreak. I could not save him, so I learned to save whoever still came through it."],world:"A settlement survives on more than walls. It survives because someone remembers the fever medicine, the clean bandages, and who has not eaten.",detail:"Mara can restore your health and refill your flasks.",voices:{greeting:["Come here. Let me see what the road did to you.","You are breathing. That is a good place to start.","Sit a moment. Hearthglen can hold without you.","Back from the tree line? I kept a needle ready."],idle:["Boil the water twice. Once is how people die.","Fresh bandages on the west shelf.","Tomas used to whistle when the gates were quiet."],farewell:["Keep pressure on anything that starts bleeding.","Come back before brave turns into foolish.","The lamp stays lit for you."],hint:["Red hearts mend flesh, but a proper rest restores your flasks.","Armor matters most when the big dead get close.","Bring me wounds, not excuses."],wounded:["That blood is yours. Sit down.","You are held together by stubbornness. Let me help.","One more hit like that and Orin will be fitting a coffin."],reaction:["Good. Take a full breath before you go.","There. Stitched, cleaned, and still alive.","Tomas would have called that a fighting chance."]}},
  maro:{history:["I started with a handcart and three tins of beans. Now I know every pass from the flooded mire to the frost line.","I trade fair because cheats get remembered, and a remembered merchant does not cross the same settlement twice."],world:"Every biome has its rumor: locked vaults in the old city, military crates under the snow, and something enormous moving beneath the Mire.",detail:"Maro buys unwanted gear and carries a rotating rare find.",voices:{greeting:["Dust on your boots and coin in your pocket. We can work with that.","Back again? Good. The road has been generous to us both.","I buy honest salvage and tell dishonest rumors.","Name your need. I have probably dragged it across three regions."],idle:["Never trust a sealed tin that bulges.","Frostfall traders pay double for clean fuel.","I once crossed the Mire on a door and bad judgment."],farewell:["Keep your pack light and your magazine full.","If you find two, sell me one.","Road willing, we trade again."],hint:["Rare keys turn up on the strongest dead.","Golden chests are worth the trouble—usually.","The old city has better loot and worse corners."],wounded:["You need Mara more than merchandise.","Try not to bleed on the rare stock.","I sell armor. That condition is a persuasive argument."],reaction:["Fair price. Fair trade.","May it keep you alive long enough to sell it back.","Pleasure doing business with someone still breathing."]}},
  elowen:{history:["I learned the bow in the old city, shooting bottles from our apartment roof. When evacuation failed, the rooftops became our only roads.","My family never reached the eastern checkpoint. I kept searching until the streets filled three bodies deep. I do not search there anymore."],world:"Strangers make noise, promise safety, then leave gates open. I trust tracks, wind, and what I can see through a sight.",detail:"Elowen watches the borders and knows where the dead gather.",voices:{greeting:["Hands where I can see them. Yes, even here.","You came back alone. That can mean skill or trouble.","Keep your voice down. Sound carries past the palisade.","I saw your tracks before I saw you."],idle:["Three dead north of the creek. Maybe four.","Wind is wrong today.","The old city still burns after rain."],farewell:["Watch the roofs as often as the road.","Step softly. Come back loudly.","If the birds stop, you stop."],hint:["Spitters hide behind the slow ones. Break their line of sight.","Scout the edge of a biome before cutting through its center.","Fog hides terrain, not consequences."],wounded:["You are leaking a trail anything can follow.","Mara. Now. I will cover you.","You look worse than the dead I passed at dawn."],reaction:["Good. You listened.","That is one less mistake waiting outside.","I will mark the safer route." ]}},
  orin:{history:["I forged hinges, plows, and wedding rings before the outbreak. Then every order became blades, bars, or nails for coffins.","A brute crushed my left shoulder at the north forge. Retirement was not my idea, but Kael has the hands to carry the work forward."],world:"Steel does not care whether you are scared. Heat it right, strike it true, and it becomes what you need.",detail:"Orin tempers weapons and reinforces armor with recovered materials.",voices:{greeting:["Set it on the bench. If it rattles, I can fix it.","You again. Good. Means the last work held.","Do not touch the tongs unless you want fewer fingers.","Let me guess—the road hit back."],idle:["Quench too fast and the steel turns brittle.","Kael! Coal first, questions second.","Used to make horseshoes. Miss the horses."],farewell:["Keep the edge dry.","Bring it back before it breaks, not after.","Steel between you and teeth. Remember that."],hint:["The heavy dead punish weak armor twice over.","Relic steel holds an edge no village forge can copy.","Save your keys for iron and gold."],wounded:["Mara first. Forge second.","No point sharpening steel for a corpse.","You look like a hammer found you."],reaction:["That will bite harder now.","Good steel. Better than when you brought it.","Try not to lose it in a zombie." ]}},
  kael:{history:["I was twelve when Orin pulled me out of a collapsed bus. Been following him around the forge ever since.","He says I rush the hammer. I do. I just want to make something strong enough that nobody else has to be pulled from wreckage."],world:"I keep count of your kills when the watch talks about them. One day I will go past the gates and earn a story like yours.",detail:"Kael is eager for field stories—and occasionally notices things the veterans miss.",voices:{greeting:["You came back! I mean—of course you did.","Can I see the weapon? Just for a second?", "Orin says not to bother you. Is this bothering you?", "Was that you shooting beyond the ridge?"],idle:["Grip lower. Strike once. No—twice.","One day I am going past that gate.","I nearly made a perfect hinge today."],farewell:["Come back with a story. A true one.","I will have something better forged next time.","Watch your back out there. I mean it."],hint:["Orin pretends not to worry when you leave.","I heard scratching under the locked chests. Maybe rats. Big rats.","The fast zombies turn wide when they charge."],wounded:["Mara! They are hurt—really hurt!", "You cannot go back out like that.","Please sit down. Heroes can sit down."],reaction:["You actually used something we made!", "That looked incredible.","I knew you could do it." ]}},
  sable:{history:["Ashwatch was twelve scouts when the smoke columns first linked across the regions. I am one of three left.","I have followed the spread from dead farmland to volcanic glass. It is not random—the hordes move as if something is pulling them."],world:"The Ember Wastes are the worst of it. Burnt dead still walk, relic-bearers guard the roads, and the Ash Tyrant keeps them moving.",detail:"Sable gives the Ember Wastes quest line and tracks its progress.",voices:{greeting:["Report. Save the comforting lies for Hearthglen.","You smell like smoke. Good—you are looking in the right direction.","The spread moved again last night.","If you came for easy work, keep walking."],idle:["Three smoke columns east. Two yesterday.","Ash preserves tracks better than mud.","The dead are migrating. I need to know why."],farewell:["Return by the wayfire. Walking back wastes daylight.","Do not chase stragglers into the smoke.","Finish the trail. Then report."],hint:["Take the Meadow wayfire, kill the five relic-bearers, then find the Tyrant.","The Ash Tyrant does twice the damage of the rank and file. Do not trade blows.","When the relic-bearers fall, the road to the Tyrant opens."],wounded:["You are no use to Ashwatch dead. Heal first.","Mara can close that. I cannot.","That wound will slow you before the Wastes do."],reaction:["One trail closed. More remain.","Ashwatch records the debt.","You did the work. Take the reward." ]}},
};
function dialogueOptions(npc:Npc,topic:DialogueTopic,save:PersistedSave):DialogueOption[]{
  if(topic==="root")return [
    {label:"Who were you before?",action:"topic",topic:"history"},
    {label:npc.id==="sable"?"What is happening in the Wastes?":"What have you seen out there?",action:"topic",topic:"world"},
    {label:npc.id==="mara"?"Treat my wounds":npc.id==="maro"?"Show me your stock":npc.id==="orin"?"Work on my gear":"Any advice?",action:npc.id==="mara"?"rest":npc.id==="maro"||npc.id==="orin"?"shop":"topic",topic:"hint"},
    {label:"I should go.",action:"leave"},
  ];
  if(topic==="history")return [{label:"What happened next?",action:"topic",topic:"historyMore"},{label:"What is it like out there?",action:"topic",topic:"world"},{label:"Ask something else",action:"topic",topic:"root"},{label:"Leave",action:"leave"}];
  if(topic==="historyMore")return [{label:"What keeps you going?",action:"topic",topic:"world"},{label:"How are things here?",action:"topic",topic:"idle"},{label:"Ask something else",action:"topic",topic:"root"},{label:"Leave",action:"leave"}];
  if(topic==="world")return [{label:"Give me one useful warning.",action:"topic",topic:"hint"},{label:"Tell me about your past.",action:"topic",topic:"history"},{label:"Ask something else",action:"topic",topic:"root"},{label:"Leave",action:"leave"}];
  const options:DialogueOption[]=[];
  if(npc.id==="sable"&&save.questState==="not_started")options.push({label:"I will take the ash road.",action:"quest"});
  if(npc.id==="sable"&&save.questState==="active"&&emberQuestProgress(save)>=EMBER_QUEST_TOTAL)options.push({label:"The Ash Tyrant is dead.",action:"quest"});
  if(npc.id==="mara")options.push({label:"Patch me up.",action:"rest"});
  if(npc.id==="maro"||npc.id==="orin")options.push({label:npc.id==="maro"?"Open your packs.":"Show me the forge.",action:"shop"});
  options.push({label:"Ask something else",action:"topic",topic:"root"},{label:"Leave",action:"leave"});
  return options.slice(0,4);
}
const EMBER_QUEST_ELITE_IDS = [1000, 1001, 1002, 1003, 1004] as const;
const EMBER_QUEST_BOSS_ID = 1005;
const EMBER_QUEST_TOTAL = 8;
function emberQuestCounts(save: PersistedSave): { travel: number; elites: number; tyrant: number } {
  return {
    travel: Number(save.questTravelOut) + Number(save.questTravelBack),
    elites: EMBER_QUEST_ELITE_IDS.filter(id => save.defeatedEnemyIds.includes(id)).length,
    tyrant: Number(save.defeatedEnemyIds.includes(EMBER_QUEST_BOSS_ID)),
  };
}
function emberQuestProgress(save: PersistedSave): number {
  const counts = emberQuestCounts(save);
  return counts.travel + counts.elites + counts.tyrant;
}
function emberQuestNext(save: PersistedSave): string {
  if (!save.questTravelOut) return "Take the Meadow wayfire to the Wastes";
  const elites = EMBER_QUEST_ELITE_IDS.filter(id => save.defeatedEnemyIds.includes(id)).length;
  if (elites < EMBER_QUEST_ELITE_IDS.length) return `Defeat relic-bearers · ${elites}/5`;
  if (!save.defeatedEnemyIds.includes(EMBER_QUEST_BOSS_ID)) return "Slay the Ash Tyrant";
  if (!save.questTravelBack) return "Return by the Wastes wayfire";
  return "Report back to Sable";
}
