type ZombieLook = { skin:string; skinLight:string; cloth:string; rot:string; eye:string; wound:string; aura:string; };
function zombieLookForZone(zone:number):ZombieLook {
  if(zone===7||zone===10)return{skin:"#3a2c29",skinLight:"#695048",cloth:"#332426",rot:"#171416",eye:"#ffbf4b",wound:"#ff5a27",aura:"rgba(255,84,32,.48)"};
  if(zone===12)return{skin:"#91abb0",skinLight:"#d4e6e7",cloth:"#49636d",rot:"#5f8996",eye:"#eaffff",wound:"#8edaf1",aura:"rgba(166,235,255,.5)"};
  if(zone===8||zone===11)return{skin:"#4f6854",skinLight:"#789078",cloth:"#29413e",rot:"#263c2e",eye:"#c6f47b",wound:"#78a968",aura:"rgba(107,180,145,.42)"};
  if(zone===9)return{skin:"#68677c",skinLight:"#9896ad",cloth:"#3d405e",rot:"#383348",eye:"#d6c7ff",wound:"#9b83ce",aura:"rgba(185,160,255,.42)"};
  if(zone===3)return{skin:"#648079",skinLight:"#91aaa0",cloth:"#31525a",rot:"#334f48",eye:"#bdf2dc",wound:"#567d70",aura:"rgba(117,193,177,.38)"};
  return{skin:"#627259",skinLight:"#8c9b79",cloth:"#39483a",rot:"#34432e",eye:"#d4f082",wound:"#684236",aura:"rgba(139,190,108,.38)"};
}
